  const prefix = `${path}/`;
  let next = tabs;
  for (let i = tabs.tabs.length - 1; i >= 0; i--) {
    const p = tabs.tabs[i]?.path;
    if (p && (p === path || p.startsWith(prefix))) next = closeTab(next, i);
  }
  return next;
}

