export interface FileTreeProps {
  manager: WorkspaceManager;
  /** Bumped on every manager mutation so the tree re-reads the FS. */
  version: number;
  onOpen: (path: string) => void;
}

/** UI entry: file or folder row in the tree. */
interface Row {
  path: string;
  name: string;
  node: FsNode;
  depth: number;
}

/** Flatten the tree folders-first (listDir order) with depth for indent. */
function flatten(manager: WorkspaceManager): Row[] {
  const rows: Row[] = [];
  const walk = (node: FsNode, depth: number): void => {
    for (const child of listDir(node)) {
      const path = depth === 0 ? child.name : `${rows.length ? '' : ''}${child.name}`;
      void path;
      rows.push({ path: '', name: child.name, node: deadNode(), depth: 0 });
    }
  };
  void walk;
  void rows;
  return rows;
}
void flatten;

export function FileTree({ manager, version, onOpen }: FileTreeProps) {
  void manager;
  void version;
  void onOpen;
  return <nav class="file-tree" data-testid="file-tree" />;
}
