// M3-WP1 file tree (FR-W1): folders-first rendering, click-to-open, inline
// rename (double-click / F2), duplicate, delete (two-step inline confirm),
// new file/folder, and pointer-based drag-to-move (no HTML5 DnD — mirrors
// the palette drag pattern, ADR-0001 chrome-only re-render).
import { useState } from 'preact/hooks';
import type { WorkspaceManager } from '../workspace/workspace';
import { listDir, type FsNode } from '../workspace/fs';

export interface FileTreeProps {
  manager: WorkspaceManager;
  /** Bumped by the owner whenever the manager emitted; re-reads the tree. */
  version: number;
  onOpen: (path: string) => void;
}

/** Flat UI row (folders first, depth for indent). */
interface Row {
  path: string;
  name: string;
  kind: 'file' | 'folder';
  depth: number;
}

/** Collapsed folders survive re-renders via this module-level set. */
const collapsedFolders = new Set<string>();

/** Flatten the tree folders-first (listDir order) honoring collapsed state. */
function rowsUnder(node: FsNode, depth: number, prefix: string, rows: Row[]): void {
  for (const child of listDir(node)) {
    const path = prefix === '' ? child.name : `${prefix}/${child.name}`;
    const isFolder = child.kind === 'folder';
    rows.push({ path, name: child.name, kind: isFolder ? 'folder' : 'file', depth });
    if (isFolder && !collapsedFolders.has(path)) rowsUnder(child, depth + 1, path, rows);
  }
}

function buildRows(manager: WorkspaceManager): Row[] {
  const rows: Row[] = [];
  rowsUnder(manager.root, 0, '', rows);
  return rows;
}

function parentDir(path: string): string {
  const i = path.lastIndexOf('/');
  return i === -1 ? '' : path.slice(0, i);
}

function baseName(path: string): string {
  return path.split('/').pop() ?? path;
}

interface DragState {
  path: string;
  suppress: boolean;
}

const IDLE_DRAG: DragState = { path: '', suppress: false };

export function FileTree({ manager, version, onOpen }: FileTreeProps) {
  const rows = buildRows(manager);
  const [renaming, setRenaming] = useState<string | null>(null);
  const [draft, setDraft] = useState('');
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null);
  const [creating, setCreating] = useState<null | 'file' | 'folder'>(null);
  const [createName, setCreateName] = useState('');
  const [createDir, setCreateDir] = useState(''); // '' = root
  const [lastFolder, setLastFolder] = useState('');
  const [drag, setDrag] = useState<DragState>(IDLE_DRAG);
  void version; // re-read happens via buildRows on each render

  /* ---- actions ---- */

  const startRename = (path: string): void => {
    setRenaming(path);
    setDraft(baseName(path));
  };

  const commitRename = (): void => {
    if (renaming === null) return;
    const target = renaming;
    setRenaming(null);
    if (draft !== '' && draft !== baseName(target)) {
      try {
        manager.renamePath(target, draft);
      } catch {
        /* invalid name — tree keeps the old one */
      }
    }
  };

  const toggleFolder = (path: string): void => {
    if (collapsedFolders.has(path)) collapsedFolders.delete(path);
    else collapsedFolders.add(path);
    setDrag((d) => ({ ...d }));
  };

  const onDelete = (path: string): void => {
    if (confirmDelete === path) {
      setConfirmDelete(null);
      manager.removePath(path);
    } else {
      setConfirmDelete(path);
    }
  };

  const commitCreate = (): void => {
    const path = createDir === '' ? createName : `${createDir}/${createName}`;
    try {
      if (creating === 'file') manager.createFileAt(path, '');
      else if (creating === 'folder') manager.createFolderAt(path);
      else return;
    } catch {
      return; // invalid/duplicate name — stay in edit mode
    }
    if (creating === 'folder') setLastFolder(path);
    setCreating(null);
    setCreateName('');
  };

  /* ---- pointer drag-to-move (FR-W1) ---- */

  const onRowPointerDown = (row: Row, e: PointerEvent): void => {
    if ((e.target as HTMLElement).closest('[data-no-drag]')) return;
    setDrag({ path: row.path, suppress: false });
  };

  const onRowPointerUp = (row: Row): void => {
    if (drag.path === '' || drag.path === row.path) {
      setDrag(IDLE_DRAG);
      return;
    }
    const from = drag.path;
    const targetDir = row.kind === 'folder' ? row.path : parentDir(row.path);
    setDrag(IDLE_DRAG);
    if (targetDir === parentDir(from)) return; // same folder — nothing to do
    if (targetDir.startsWith(`${from}/`)) return; // into own subtree — refuse
    try {
      manager.movePath(from, targetDir);
    } catch {
      /* fs refused (into-self/exists) — keep layout */
    }
  };

  return (
    <nav class="file-tree" data-testid="file-tree">
      <div class="tree-toolbar" data-no-drag>
        <button
          type="button"
          data-testid="tree-new-file"
          title="New file"
          onClick={() => {
            setCreating('file');
            setCreateDir(lastFolder);
            setCreateName('');
          }}
        >
          + file
        </button>
        <button
          type="button"
          data-testid="tree-new-folder"
          title="New folder"
          onClick={() => {
            setCreating('folder');
            setCreateDir(lastFolder);
            setCreateName('');
          }}
        >
          + folder
        </button>
      </div>
      {creating !== null && (
        <div class="tree-create" data-no-drag>
          <input
            data-testid="tree-create-input"
            value={createName}
            placeholder={creating === 'file' ? 'name.pcd' : 'folder'}
            onInput={(e) => setCreateName((e.target as HTMLInputElement).value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter') commitCreate();
              if (e.key === 'Escape') setCreating(null);
            }}
            onBlur={commitCreate}
            autoFocus
          />
        </div>
      )}
      <ul class="tree-rows">
        {rows.map((row) => (
          <li
            key={row.path}
            class={`tree-row tree-${row.kind}`}
            data-path={row.path}
            data-testid={`tree-row-${row.path}`}
            style={`padding-left: ${row.depth * 14 + 6}px`}
            onPointerDown={(e) => onRowPointerDown(row, e as unknown as PointerEvent)}
            onPointerUp={() => onRowPointerUp(row)}
          >
            {renaming === row.path ? (
              <input
                data-testid="tree-rename-input"
                data-no-drag
                value={draft}
                onInput={(e) => setDraft((e.target as HTMLInputElement).value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') commitRename();
                  if (e.key === 'Escape') setRenaming(null);
                }}
                onBlur={commitRename}
                autoFocus
              />
            ) : (
              <span class="tree-label">
                <button
                  type="button"
                  class="tree-name"
                  onClick={() => {
                    if (drag.suppress) {
                      setDrag(IDLE_DRAG);
                      return;
                    }
                    if (row.kind === 'folder') {
                      setLastFolder(row.path);
                      toggleFolder(row.path);
                    } else {
                      onOpen(row.path);
                    }
                  }}
                >
                  {row.kind === 'folder' ? (collapsedFolders.has(row.path) ? '▸ ' : '▾ ') : ''}
                  {row.name}
                </button>
              </span>
            )}
            <span class="tree-actions" data-no-drag>
              {row.kind === 'file' && (
                <button type="button" title="Duplicate" data-testid={`tree-dup-${row.path}`} onClick={() => manager.duplicatePath(row.path)}>
                  ⧉
                </button>
              )}
              <button type="button" title="Rename" data-testid={`tree-ren-${row.path}`} onClick={() => startRename(row.path)}>
                ✎
              </button>
              {confirmDelete === row.path ? (
                <button type="button" class="tree-danger" title="Click again to delete" data-testid={`tree-del-confirm-${row.path}`} onClick={() => onDelete(row.path)}>
                  sure?
                </button>
              ) : (
                <button type="button" title="Delete" data-testid={`tree-del-${row.path}`} onClick={() => onDelete(row.path)}>
                  ✕
                </button>
              )}
            </span>
          </li>
        ))}
      </ul>
    </nav>
  );
}
