:root {
  color-scheme: light dark;
  --pc-bg: #ffffff;
  --pc-surface: #f5f6f8;
  --pc-fg: #1a1d21;
  --pc-muted: #6b7280;
  --pc-accent: #2563eb;
  --pc-border: #d1d5db;
  --pc-canvas: #fafafa;
  --pc-text-xs: 11px;
  --pc-text-sm: 12px;
  --pc-text-md: 14px;
  --pc-radius-sm: 4px;
  --pc-radius-md: 8px;
}

@media (prefers-color-scheme: dark) {
  :root {
    --pc-bg: #14161a;
    --pc-surface: #1e2126;
    --pc-fg: #e5e7eb;
    --pc-muted: #9ca3af;
    --pc-accent: #60a5fa;
    --pc-border: #374151;
    --pc-canvas: #111316;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--pc-bg);
  color: var(--pc-fg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

.app-shell {
  display: flex;
  flex-direction: column;
  height: 100vh;
}

.app-header {
  display: flex;
  align-items: baseline;
  gap: 12px;
  padding: 8px 16px;
  border-bottom: 1px solid var(--pc-border);
  background: var(--pc-surface);
}

.app-title {
  font-weight: 600;
}

