{"content":"// SPDX-License-Identifier: GPL-3.0-only
// App shell (M3): file tree | tabs | palette | canvas | properties, workspace
// chrome + toolbar. The canvas owns its imperative controller (ADR-0001:
// Preact renders chrome around the SVG, never inside it); the WorkspaceManager
// owns the virtual FS + autosave and re-renders chrome via subscribe().
// Canvas ⇄ file sync: loading a file pushes manager.canvasState into
// ctrl.loadState (guard flag suppresses the echo save); every controller state
// change flows back through manager.saveCanvas (content-compare makes clean
// saves no-ops, so position-only drags don't rewrite the file).
import { useEffect, useRef, useState } from 'preact/hooks';
import { CanvasController, PALETTE_ORDER, labelFor, type Snapshot } from './CanvasController';
import type { Kind } from '../engine/model/types';
import { PropertiesPanel } from './PropertiesPanel';
import { Palette } from './Palette';
import { FileTree } from './FileTree';
import { Tabs } from './Tabs';
import { WorkspaceManager } from '../workspace/workspace';
import { exportPng, exportSvg, PCARD_IMPORT_EXTS } from '../workspace/io';
import { downloadBlob, downloadText, readFileAsBytes, readFileAsText } from './download';

/** Structurally-equal empty DiagramState (controller + manager share shape). */
const EMPTY_STATE = { objects: [], links: [] };

function baseName(p: string): string {
  return p.split('/').pop() ?? p;
}

function stem(p: string): string {
  return baseName(p).replace(/\.[^.]*$/, '');
}

export function App() {
  const svgRef = useRef<SVGSVGElement | null>(null);
  const ctrlRef = useRef<CanvasController | null>(null);
  const managerRef = useRef<WorkspaceManager | null>(null);
  const nameFieldRef = useRef<HTMLInputElement | null>(null);
  const importFilesRef = useRef<HTMLInputElement | null>(null);
  const importZipRef = useRef<HTMLInputElement | null>(null);
  const lastLoadedRef = useRef<string | null>(null);
  const loadingRef = useRef<string | null>(null);
  if (managerRef.current === null) managerRef.current = new WorkspaceManager();
  const manager = managerRef.current;

  const [ready, setReady] = useState(false);
  const [version, setVersion] = useState(0);
  const [snap, setSnap] = useState<Snapshot | null>(null);
  const [errorFlash, setErrorFlash] = useState<string | null>(null);
  const [dismissedError, setDismissedError] = useState<string | null>(null);
  const [clearOpen, setClearOpen] = useState(false);
  const [clearConfirm, setClearConfirm] = useState('');
  const [ephemeralReminder, setEphemeralReminder] = useState(false);

  /* ---- workspace lifecycle ---- */

  useEffect(() => {
    let disposed = false;
    void manager.init().then(() => {
      if (!disposed) setReady(true);
    });
    const unsub = manager.subscribe(() => setVersion((v) => v + 1));
    return () => {
      disposed = true;
      unsub();
    };
  }, [manager]);

  /* FR-S1: commit autosave when the tab hides or unloads. */
  useEffect(() => {
    const flush = (): void => {
      void manager.flush();
    };
    const onVisible = (): void => {
      if (document.hidden) flush();
    };
    window.addEventListener('beforeunload', flush);
    document.addEventListener('visibilitychange', onVisible);
    return () => {
      window.removeEventListener('beforeunload', flush);
      document.removeEventListener('visibilitychange', onVisible);
    };
  }, [manager]);

  /* FR-S2: private-mode reminder every 10 minutes of active private session. */
  useEffect(() => {
    if (!ready || !manager.ephemeral) return;
    setEphemeralReminder(false);
    const timer = window.setInterval(() => setEphemeralReminder(true), 600_000);
    return () => window.clearInterval(timer);
  }, [ready, manager.ephemeral, version]);

  /* ---- active file ⇄ canvas sync ---- */

  useEffect(() => {
    if (!ready) return;
    const ctrl = ctrlRef.current;
    if (!ctrl) return;
    const path = manager.activePath;
    if (path === lastLoadedRef.current) return;
    if (path === null) {
      lastLoadedRef.current = null;
      loadingRef.current = '\u0000';
      ctrl.loadState(EMPTY_STATE);
      loadingRef.current = null;
      return;
    }
    lastLoadedRef.current = path;
    loadingRef.current = path;
    ctrl.loadState(manager.canvasState(path));
    loadingRef.current = null;
    manager.markClean(path);
  }, [ready, version, manager]);

  const onCtrlState = (s: Snapshot): void => {
    setSnap({ ...s });
    const path = manager.activePath;
    if (path !== null && loadingRef.current !== path) {
      manager.saveCanvas(path, { objects: s.objects, links: s.links });
    }
  };

  useEffect(() => {
    const svg = svgRef.current;
    if (!svg || ctrlRef.current) return;
    const ctrl = new CanvasController(svg, {
      onState: onCtrlState,
      onRenameRequest: () => nameFieldRef.current?.focus(),
    });
    ctrlRef.current = ctrl;
    return () => {
      ctrl.destroy();
      ctrlRef.current = null;
    };
  }, []);

  /* ---- palette (M2 behavior, unchanged) ---- */

  const onPaletteDrop = (kind: Kind, e: PointerEvent): void => {
    const ctrl = ctrlRef.current;
    if (!ctrl) return;
    const rect = svgRef.current?.getBoundingClientRect();
    if (!rect) return;
    const p = ctrl.viewport;
    const canvasPt = {
      x: (e.clientX - rect.left - p.x) / p.k,
      y: (e.clientY - rect.top - p.y) / p.k,
    };
    ctrl.addObject(kind, canvasPt);
  };

  /* ---- toolbar handlers (FR-W3/W4/W5) ---- */

  const activePath = ready ? manager.activePath : null;

  const flash = (err: unknown): void => {
    setErrorFlash(err instanceof Error ? err.message : String(err));
  };

  const exportPcd = (): void => {
    if (activePath === null) return;
    downloadText(manager.exportText(activePath, '.pcd'), baseName(activePath));
  };

  const exportMmd = (): void => {
    if (activePath === null) return;
    downloadText(manager.exportText(activePath, '.mmd'), `${stem(activePath)}.mmd`, 'text/plain');
  };

  const exportSvgHandler = (): void => {
    const svg = svgRef.current;
    if (svg === null || activePath === null) return;
    downloadText(exportSvg(svg), `${stem(activePath)}.svg`, 'image/svg+xml');
  };

  const exportPngHandler = (): void => {
    const svg = svgRef.current;
    if (svg === null || activePath === null) return;
    exportPng(svg)
      .then((out) => downloadBlob(out.blob, `${stem(activePath)}.png`))
      .catch(flash);
  };

  const exportZip = (): void => {
    manager
      .exportZip()
      .then((blob) => downloadBlob(blob, `${manager.name}.zip`))
      .catch(flash);
  };

  const onImportFiles = async (list: FileList | null): Promise<void> => {
    if (list === null || list.length === 0) return;
    const files = await Promise.all(
      [...list].map(async (f) => ({ name: f.name, text: await readFileAsText(f) })),
    );
    manager.importFiles(files);
  };

  const onImportZip = async (list: FileList | null): Promise<void> => {
    const file = list?.item(0);
    if (!file) return;
    const bytes = await readFileAsBytes(file);
    await manager.importZip(bytes);
  };

  const toggleEphemeral = (on: boolean): void => {
    setEphemeralReminder(false);
    void manager.setEphemeral(on);
  };

  const clearData = async (): Promise<void> => {
    await manager.clearAll();
    lastLoadedRef.current = null;
    setClearOpen(false);
    setClearConfirm('');
  };

  const ctrl = ctrlRef.current;
  const selectedObj =
    snap && snap.selection.objects.length === 1
      ? snap.objects.find((o) => o.id === snap.selection.objects[0]) ?? null
      : null;
  const selectedLink =
    snap && snap.selection.links.length === 1
      ? snap.links.find((l) => l.id === snap.selection.links[0]) ?? null
      : null;

  const showOpenError = ready && manager.openError !== null && manager.openError !== dismissedError;
  const showQuota = ready && manager.quotaDegraded;
  const showEphemeralBadge = ready && manager.ephemeral && !manager.quotaDegraded;

  return (
    <div class="app-shell" data-testid="app-shell">
      <header class="app-header">
        <span class="app-title">PanelCraft</span>
        <span class="muted">M3 workspace — autosaved in your browser</span>
        <span class="toolbar">
          <button type="button" data-testid="tb-import-files" onClick={() => importFilesRef.current?.click()}>
            Import…
          </button>
          <button type="button" data-testid="tb-import-zip" onClick={() => importZipRef.current?.click()}>
            Open ZIP
          </button>
          <button type="button" data-testid="tb-export-pcd" disabled={activePath === null} onClick={exportPcd}>
            .pcd
          </button>
          <button type="button" data-testid="tb-export-mmd" disabled={activePath === null} onClick={exportMmd}>
            .mmd
          </button>
          <button type="button" data-testid="tb-export-svg" disabled={activePath === null} onClick={exportSvgHandler}>
            .svg
          </button>
          <button type="button" data-testid="tb-export-png" disabled={activePath === null} onClick={exportPngHandler}>
            .png
          </button>
          <button type="button" data-testid="tb-export-zip" onClick={exportZip}>
            ZIP
          </button>
          <label class="toolbar-check" data-testid="tb-ephemeral" title="Private mode: keep this session in memory only (FR-S2)">
            <input
              type="checkbox"
              checked={ready && manager.ephemeral}
              onChange={(e) => toggleEphemeral((e.target as HTMLInputElement).checked)}
            />
            private
          </label>
          <button type="button" class="tb-danger" data-testid="tb-clear-data" onClick={() => setClearOpen(true)}>
            Clear data…
          </button>
        </span>
      </header>
      <div class="banners">
        {showOpenError && (
          <div class="banner banner-error" data-testid="banner-open-error" role="alert">
            <span>Could not open saved workspace: {manager.openError}</span>
            <button type="button" onClick={() => setDismissedError(manager.openError)}>dismiss</button>
          </div>
        )}
        {showQuota && (
          <div class="banner banner-warn" data-testid="banner-quota" role="alert">
            <span>Storage quota exceeded — this session is in-memory only (FR-S3).</span>
          </div>
        )}
        {(showEphemeralBadge || ephemeralReminder) && (
          <div class="banner banner-warn" data-testid="banner-ephemeral" role="status">
            <span>
              {ephemeralReminder
                ? 'Reminder: private mode is on — changes are not persisted (FR-S2).'
                : 'Private mode: changes are kept in memory only.'}
            </span>
            {ephemeralReminder && (
              <button type="button" onClick={() => setEphemeralReminder(false)}>dismiss</button>
            )}
          </div>
        )}
        {errorFlash !== null && (
          <div class="banner banner-error" data-testid="banner-flash" role="alert">
            <span>{errorFlash}</span>
            <button type="button" onClick={() => setErrorFlash(null)}>dismiss</button>
          </div>
        )}
      </div>
      <div class="app-body">
        <aside class="sidebar">
          <FileTree manager={manager} version={version} onOpen={(p) => manager.openFile(p)} />
        </aside>
        <Palette kinds={PALETTE_ORDER} onPlace={(k) => ctrl?.addObject(k)} onDragDrop={onPaletteDrop} />
        <main class="canvas-col">
          <Tabs
            tabs={manager.tabs.tabs}
            active={manager.tabs.active}
            onSelect={(i) => {
              const t = manager.tabs.tabs[i];
              if (t) manager.openFile(t.path);
            }}
            onClose={(i) => manager.closeTabAt(i)}
            onReorder={(from, to) => manager.moveTabAt(from, to)}
          />
          <main class="canvas-wrap">
            <svg ref={svgRef} class="pc-canvas" data-testid="canvas" width="100%" height="100%" />
          </main>
        </main>
        <PropertiesPanel
          obj={selectedObj}
          link={selectedLink}
          nameFieldRef={nameFieldRef}
          onChangeObject={(id, patch) => ctrl?.updateObject(id, patch)}
          onChangeLink={(id, patch) => ctrl?.updateLink(id, patch)}
        />
      </div>
      {clearOpen && (
        <div class="dialog-overlay" data-testid="clear-dialog" role="dialog" aria-modal="true" aria-label="Clear stored data">
          <div class="dialog">
            <h2 class="dialog-title">Clear all workspace data?</h2>
            <p class="dialog-text">
              This deletes every file in the workspace and the autosaved copy in
              browser storage. Type <code>DELETE</code> to confirm (FR-S4).
            </p>
            <input
              data-testid="clear-confirm-input"
              value={clearConfirm}
              placeholder="DELETE"
              onInput={(e) => setClearConfirm((e.target as HTMLInputElement).value)}
              onKeyDown={(e) => {
                if (e.key === 'Escape') setClearOpen(false);
              }}
            />
            <div class="dialog-actions">
              <button type="button" onClick={() => setClearOpen(false)}>Cancel</button>
              <button
                type="button"
                class="tb-danger"
                data-testid="clear-confirm-btn"
                disabled={clearConfirm !== 'DELETE'}
                onClick={() => void clearData()}
              >
                Delete everything
              </button>
            </div>
          </div>
        </div>
      )}
      <input
        ref={importFilesRef}
        type="file"
        multiple
        accept=".pcd,.mmd,.mermaid,.txt"
        data-testid="import-files-input"
        class="visually-hidden"
        onChange={(e) => {
          void onImportFiles((e.target as HTMLInputElement).files);
          (e.target as HTMLInputElement).value = '';
        }}
      />
      <input
        ref={importZipRef}
        type="file"
        accept=".zip"
        data-testid="import-zip-input"
        class="visually-hidden"
        onChange={(e) => {
          void onImportZip((e.target as HTMLInputElement).files);
          (e.target as HTMLInputElement).value = '';
        }}
      />
    </div>
  );
}

